// The share card (1200x675 PNG) for every page: brief/images/product-line-v2.svg rendered with Inter.
// Served at /og.png; og:image and twitter:image point here.
export const OG_PNG_B64 = "";
let bytes = null;
export function ogPng() {
  if (!bytes) bytes = Uint8Array.from(atob(OG_PNG_B64), (c) => c.charCodeAt(0));
  return bytes;
}
